    @BeforeEach void fixture() {
        assertEquals("studyroom_java_test",db.one("SELECT current_database() AS name").get("name"));
        TestDatabaseCleanup.clear(db);
        base=LocalDate.now(BookingPolicy.CAMPUS_ZONE).minusDays(1);clock.set(base.atTime(9,0));remote="s21-test-"+UUID.randomUUID();
        String hash=new BCryptPasswordEncoder().encode("S02-test-only-password");
        admin=db.insert("INSERT INTO users(username,password_hash,role,campus_id) VALUES('s21_admin',?,'admin','S09-admin')",hash);
        student=db.insert("INSERT INTO users(username,password_hash,role,campus_id) VALUES('s21_student',?,'student','S09-student')",hash);
        staff=db.insert("INSERT INTO users(username,password_hash,role,campus_id) VALUES('s21_staff',?,'staff','S09-staff')",hash);
        other=db.insert("INSERT INTO users(username,password_hash,role,campus_id) VALUES('s21_other',?,'student','S14-other')",hash);
        room=db.insert("INSERT INTO rooms(name,seat_rows,seat_cols) VALUES('S14模拟空间',1,2)");opening.initializeDefaults(room);
        seat1=db.insert("INSERT INTO seats(room_id,seat_no,row_no,col_no) VALUES(?,'01',1,1)",room);seat2=db.insert("INSERT INTO seats(room_id,seat_no,row_no,col_no) VALUES(?,'02',1,2)",room);
    }
    @AfterEach void clearRate() { redis.delete("studyroom-java:rate:login:"+remote); }
    void at(int h,int m,int s) { clock.set(base.atTime(h,m,s)); }
    String token(String role) throws Exception {
        var result=http.perform(post("/api/auth/login").with(r->{r.setRemoteAddr(remote);return r;}).contentType("application/json").content(json.writeValueAsString(Map.of("username","s21_"+role,"password","S02-test-only-password")))).andExpect(status().isOk()).andReturn();
        return json.readTree(result.getResponse().getContentAsString()).path("data").path("token").asText();
    }
    long reservation(long user,long seat) { return Store.id(bookings.create(user,new Requests.Reservation(seat,base.toString(),"10:00","11:00")),"id"); }
    String code(long seat) { codes.generate(admin,seat,new Requests.SeatCodeChange(0L,"测试实际生成座位码"));return current(seat); }
    String current(long seat) { return Store.text(db.one("SELECT code_value FROM seat_codes WHERE seat_id=?",seat),"code_value"); }
    String path(long seat) { return "/api/admin/seats/"+seat+"/code"; }
    MockHttpServletRequestBuilder auth(MockHttpServletRequestBuilder req,String token) { return req.header("Authorization","Bearer "+token); }
    MockHttpServletRequestBuilder checkin(long id,String code,String token) throws Exception { return auth(post("/api/reservations/"+id+"/checkin"),token).contentType("application/json").content(json.writeValueAsString(Map.of("seat_code",code))); }
    Map<String,Object> row(long id) { return db.one("SELECT * FROM reservations WHERE id=?",id); }
    static byte[] image(String format,int width,int height) throws Exception { var image=new BufferedImage(width,height,BufferedImage.TYPE_INT_RGB);var output=new ByteArrayOutputStream();assertTrue(ImageIO.write(image,format,output));image.flush();return output.toByteArray(); }

    String key(){return UUID.randomUUID().toString();}
    LocalDateTime now(){return LocalDateTime.ofInstant(clock.instant(),BookingPolicy.CAMPUS_ZONE).truncatedTo(java.time.temporal.ChronoUnit.MICROS);}
    long violation(long owner,LocalDateTime notified){long reservation=db.insert("INSERT INTO reservations(user_id,seat_id,res_date,start_time,end_time,status,ended_at,termination_reason) VALUES(?,?,?,'08:00','09:00','unused_ended',?,'no_show')",owner,seat1,java.sql.Date.valueOf(base),java.sql.Timestamp.valueOf(base.atTime(8,15)));long id=db.insert("INSERT INTO violations(user_id,reservation_id,type,event_key,occurred_at,registered_at,status,reason,source) VALUES(?,?,'no_show',?,?,?,'active','S21明确工程模拟原违规事实说明','automatic')",owner,reservation,"unused:"+reservation,java.sql.Timestamp.valueOf(base.atTime(8,15)),java.sql.Timestamp.valueOf(base.atTime(8,20)));if(notified!=null)db.insert("INSERT INTO notifications(user_id,type,title,content,violation_id,created_at) VALUES(?,'violation','真实typed工程模拟通知','通知仅表明系统已生成，不证明用户已读',?,?)",owner,id,java.sql.Timestamp.valueOf(notified));return id;}
    Requests.Appeal request(List<String> ids){return new Requests.Appeal(key(),"  工程模拟：本人申诉说明，并非已经审核成立  ",ids);}
    long appealId(Map<String,Object> receipt){return ((Number)((Map<?,?>)receipt.get("appeal")).get("id")).longValue();}
    String createPath(long id){return "/api/violations/"+id+"/appeals";}
    String eligibilityPath(long id){return "/api/violations/"+id+"/appeal-eligibility";}
    MockHttpServletRequestBuilder body(MockHttpServletRequestBuilder req,Object payload,String token)throws Exception{return auth(req,token).contentType("application/json").content(json.writeValueAsString(payload));}
    String file(long owner,String format)throws Exception{return attachments.upload(owner,new MockMultipartFile("file","../../untrusted.html","text/html",image(format,8,8)),AttachmentService.Purpose.APPEAL).get("id").toString();}
    String tables(List<String> names){var result=new LinkedHashMap<String,Object>();for(String table:names)result.put(table,db.list("SELECT to_jsonb(t)::text AS value FROM "+table+" t ORDER BY to_jsonb(t)::text"));return result.toString();}
    String penalties(){return tables(List.of("users","reservations","usage_records","violations","restrictions","restriction_evaluations","restriction_evaluation_sources","notifications","credit_logs","complaints","complaint_events"));}
    String facts(){return penalties()+tables(List.of("appeals","appeal_events","evidence_attachments","audit_events"));}
    @Test void ownerSubmitsAndReadsProgressWhileAdminHasReadOnlyPendingAndOriginalFactsRemain()throws Exception{
        String owner=token("student"),administrator=token("admin");long id=violation(student,now());String before=penalties();var response=http.perform(body(post(createPath(id)),request(List.of()),owner)).andExpect(status().isOk()).andExpect(jsonPath("$.data.replayed").value(false)).andExpect(jsonPath("$.data.appeal.status").value("submitted")).andExpect(jsonPath("$.data.appeal.description").value("工程模拟：本人申诉说明，并非已经审核成立")).andExpect(jsonPath("$.data.appeal.events[0].type").value("submitted")).andExpect(jsonPath("$.data.appeal.violation_snapshot.status").value("active")).andReturn();long appeal=json.readTree(response.getResponse().getContentAsString()).path("data").path("appeal").path("id").asLong();assertEquals(before,penalties());http.perform(auth(get("/api/appeals/mine"),owner)).andExpect(status().isOk()).andExpect(jsonPath("$.data[0].id").value(appeal));http.perform(auth(get("/api/appeals/"+appeal),owner)).andExpect(status().isOk()).andExpect(jsonPath("$.data.notification_basis.notified_at").value(base+"T09:00+08:00"));http.perform(auth(get("/api/admin/appeals"),administrator)).andExpect(status().isOk()).andExpect(jsonPath("$.data[0].subject.id").value(student));http.perform(auth(get("/api/admin/appeals/"+appeal),administrator)).andExpect(status().isOk()).andExpect(jsonPath("$.data.subject.role").value("student")).andExpect(jsonPath("$.data.management_context.violation.id").value(id)).andExpect(jsonPath("$.data.management_context.violation.reservation_id").value(Store.id(db.one("SELECT reservation_id FROM violations WHERE id=?",id),"reservation_id"))).andExpect(jsonPath("$.data.management_context.violation.source_event_id").isEmpty()).andExpect(jsonPath("$.data.management_context.violation.registrant_id").isEmpty()).andExpect(jsonPath("$.data.management_context.source_complaint_id").isEmpty());assertEquals(before,penalties());assertEquals(1,db.count("SELECT count(*) FROM appeal_events"));assertEquals(1,db.count("SELECT count(*) FROM audit_events WHERE action='appeal.submit'"));
    }
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"before","at_notification","last_microsecond","at_deadline"})
    void realTypedNotificationAloneDefinesHalfOpenSevenDayMicrosecondWindow(String boundary)throws Exception{
        String owner=token("student");LocalDateTime notification=base.atTime(9,0,0,123456000);long id=violation(student,notification);clock.set(switch(boundary){case "before"->notification.minusNanos(1000);case "at_notification"->notification;case "last_microsecond"->notification.plusHours(168).minusNanos(1000);default->notification.plusHours(168);});boolean valid=boundary.equals("at_notification")||boundary.equals("last_microsecond");String blocked=valid?null:boundary.equals("before")?"before_notification":"deadline_passed";var qualification=appeals.eligibility(student,id);assertEquals(valid,((Map<?,?>)qualification.get("eligibility")).get("can_submit"));assertEquals(blocked,((Map<?,?>)qualification.get("eligibility")).get("blocked_by"));var action=http.perform(body(post(createPath(id)),request(List.of()),owner));if(valid)action.andExpect(status().isOk());else action.andExpect(status().isConflict()).andExpect(jsonPath("$.details.code").value("appeal_not_eligible")).andExpect(jsonPath("$.details.eligibility.blocked_by").value(blocked));assertEquals(valid?1:0,db.count("SELECT count(*) FROM appeals"));
    }
    @Test void unknownNotificationIsNotGuessedFromRegistrationOrSimilarUntypedText()throws Exception{String owner=token("student");long id=violation(student,null);db.insert("INSERT INTO notifications(user_id,type,title,content,created_at) VALUES(?,'violation','旧违规通知','看似相同的标题不能认成真实typed依据',?)",student,java.sql.Timestamp.valueOf(now()));String before=facts();http.perform(auth(get(eligibilityPath(id)),owner)).andExpect(status().isOk()).andExpect(jsonPath("$.data.eligibility.blocked_by").value("notification_unknown")).andExpect(jsonPath("$.data.eligibility.deadline").isEmpty());http.perform(body(post(createPath(id)),request(List.of()),owner)).andExpect(status().isConflict()).andExpect(jsonPath("$.details.eligibility.blocked_by").value("notification_unknown"));assertEquals(before,facts());}
    @Test void successfulOperationReplaysPureAfterDeadlineRevocationAndCanonicalNormalization()throws Exception{long id=violation(student,now());String one=file(student,"png"),two=file(student,"jpeg");var request=request(List.of(one.toUpperCase(Locale.ROOT),two));var first=appeals.create(student,id,request);long appeal=appealId(first);db.update("UPDATE violations SET status='revoked' WHERE id=?",id);clock.set(now().plusHours(169));String before=facts();var replay=appeals.create(student,id,new Requests.Appeal(request.operationId().toUpperCase(Locale.ROOT),request.description().trim(),List.of(one,two)));assertEquals(true,replay.get("replayed"));assertEquals(appeal,appealId(replay));assertEquals(before,facts());assertEquals("active",((Map<?,?>)((Map<?,?>)replay.get("appeal")).get("violation_snapshot")).get("status"));assertEquals(409,assertThrows(Api.Failure.class,()->appeals.create(student,id,new Requests.Appeal(request.operationId(),request.description(),List.of(two,one)))).status);assertEquals(409,assertThrows(Api.Failure.class,()->appeals.create(student,id,new Requests.Appeal(request.operationId(),"changed",List.of(one,two)))).status);assertEquals(409,assertThrows(Api.Failure.class,()->appeals.create(other,id,request)).status);}
    @Test void duplicatePendingGivesOnlyOwnerExistingAndRevokedPrecedenceDoesNotOverwriteHistory()throws Exception{String owner=token("student");long id=violation(student,now());long appeal=appealId(appeals.create(student,id,request(List.of())));http.perform(body(post(createPath(id)),request(List.of()),owner)).andExpect(status().isConflict()).andExpect(jsonPath("$.details.code").value("appeal_pending")).andExpect(jsonPath("$.details.existing_appeal.id").value(appeal));db.update("UPDATE violations SET status='revoked' WHERE id=?",id);http.perform(auth(get(eligibilityPath(id)),owner)).andExpect(status().isOk()).andExpect(jsonPath("$.data.eligibility.blocked_by").value("revoked")).andExpect(jsonPath("$.data.eligibility.existing_appeal.id").value(appeal));assertEquals(1,db.count("SELECT count(*) FROM appeals"));}
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(booleans={false,true})
    void concurrentSameOrDifferentOperationKeysProduceOnePendingAppeal(boolean same)throws Exception{long id=violation(student,now());var a=request(List.of());var b=same?a:request(List.of());var barrier=new CyclicBarrier(2);var pool=Executors.newFixedThreadPool(2);try{var first=pool.submit(()->{barrier.await();try{appeals.create(student,id,a);return 200;}catch(Api.Failure e){return e.status;}});var second=pool.submit(()->{barrier.await();try{appeals.create(student,id,b);return 200;}catch(Api.Failure e){return e.status;}});var statuses=List.of(first.get(20,TimeUnit.SECONDS),second.get(20,TimeUnit.SECONDS));assertEquals(same?2:1,statuses.stream().filter(code->code==200).count());assertEquals(same?0:1,statuses.stream().filter(code->code==409).count());}finally{pool.shutdownNow();}assertEquals(1,db.count("SELECT count(*) FROM appeals"));assertEquals(1,db.count("SELECT count(*) FROM appeal_events"));assertEquals(1,db.count("SELECT count(*) FROM audit_events WHERE action='appeal.submit'"));}
    @Test void allAppealReadsAndSubmissionDoNotAssessThreeUnusedViolationsOrSettleExpiredReservations(){long id=violation(student,now());violation(student,now());violation(student,now());long pending=db.insert("INSERT INTO reservations(user_id,seat_id,res_date,start_time,end_time,status) VALUES(?,?,?,'08:00','10:00','pending')",student,seat2,java.sql.Date.valueOf(base));String before=penalties();appeals.eligibility(student,id);long appeal=appealId(appeals.create(student,id,request(List.of())));appeals.mine(student);appeals.detail(student,appeal);appeals.listAdmin(admin,null);appeals.detailAdmin(admin,appeal);assertEquals(before,penalties());assertEquals("pending",row(pending).get("status"));assertEquals(0,db.count("SELECT count(*) FROM restrictions"));}
    @Test void pngJpegPurposeContentAndOwnershipRemainByteExactBeforeAndAfterBinding()throws Exception{String owner=token("student"),administrator=token("admin"),foreign=token("other");long id=violation(student,now());byte[] png=image("png",16,16),jpeg=image("jpeg",12,12);var result=http.perform(multipart("/api/appeal-attachments").file(new MockMultipartFile("file","../../private.html","text/html",png)).header("Authorization","Bearer "+owner)).andExpect(status().isOk()).andExpect(jsonPath("$.data.content_type").value("image/png")).andReturn();String first=json.readTree(result.getResponse().getContentAsString()).path("data").path("id").asText();String second=attachments.upload(student,new MockMultipartFile("file","wrong.png","image/png",jpeg),AttachmentService.Purpose.APPEAL).get("id").toString();http.perform(auth(get("/api/appeal-attachments/"+first),owner)).andExpect(status().isOk()).andExpect(header().string("X-Content-Type-Options","nosniff")).andExpect(header().string("Cache-Control","no-store")).andExpect(content().bytes(png));http.perform(auth(get("/api/appeal-attachments/"+first),administrator)).andExpect(status().isForbidden());http.perform(auth(get("/api/appeal-attachments/"+first),foreign)).andExpect(status().isForbidden());http.perform(auth(get("/api/complaint-attachments/"+first+"/content"),owner)).andExpect(status().isNotFound());long appeal=appealId(appeals.create(student,id,request(List.of(first,second))));assertArrayEquals(png,attachments.content(admin,first,AttachmentService.Purpose.APPEAL).bytes());assertArrayEquals(jpeg,attachments.content(student,second,AttachmentService.Purpose.APPEAL).bytes());http.perform(auth(get("/api/appeals/"+appeal),owner)).andExpect(status().isOk()).andExpect(jsonPath("$.data.attachments[0].id").value(first)).andExpect(jsonPath("$.data.attachments[1].id").value(second)).andExpect(jsonPath("$.data.attachments[0].expires_at").isEmpty());clock.set(now().plusDays(20));assertEquals(0,attachments.cleanupExpired());assertArrayEquals(png,attachments.content(student,first,AttachmentService.Purpose.APPEAL).bytes());}
    @Test void noCrossPurposeReuseEvenSameOwnerAndNoForeignOrAlreadyBoundEvidence(){long id=violation(student,now());String complaint=attachments.upload(student,new MockMultipartFile("file","old.png","image/png",uncheckedImage()),AttachmentService.Purpose.COMPLAINT).get("id").toString();assertEquals(400,assertThrows(Api.Failure.class,()->appeals.create(student,id,request(List.of(complaint)))).status);String otherFile=attachments.upload(other,new MockMultipartFile("file","foreign.png","image/png",uncheckedImage()),AttachmentService.Purpose.APPEAL).get("id").toString();assertEquals(403,assertThrows(Api.Failure.class,()->appeals.create(student,id,request(List.of(otherFile)))).status);String own=attachments.upload(student,new MockMultipartFile("file","own.png","image/png",uncheckedImage()),AttachmentService.Purpose.APPEAL).get("id").toString();appeals.create(student,id,request(List.of(own)));long another=violation(student,now());assertEquals(409,assertThrows(Api.Failure.class,()->appeals.create(student,another,request(List.of(own)))).status);assertEquals(400,assertThrows(Api.Failure.class,()->complaints.create(student,new Requests.Complaint("service",null,null,"用途不匹配",List.of(own),key()))).status);assertEquals(1,db.count("SELECT count(*) FROM appeals"));}
    byte[] uncheckedImage(){try{return image("png",4,4);}catch(Exception e){throw new IllegalStateException(e);}}
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"event","binding","audit"})
    void anySubmissionDependencyFailureRollsBackAppealEventAndEveryEvidenceBinding(String layer)throws Exception{String owner=token("student");long id=violation(student,now());String first=file(student,"png"),second=file(student,"jpeg");String before=facts();String table=layer.equals("event")?"appeal_events":layer.equals("binding")?"evidence_attachments":"audit_events",condition=layer.equals("event")?"event_type<>'submitted'":layer.equals("binding")?"appeal_id IS NULL OR position<>1":"action<>'appeal.submit'";db.update("ALTER TABLE "+table+" ADD CONSTRAINT s21_fail CHECK("+condition+") NOT VALID");try{http.perform(body(post(createPath(id)),request(List.of(first,second)),owner)).andExpect(status().isInternalServerError());assertEquals(before,facts());assertEquals(0,db.count("SELECT count(*) FROM appeals"));}finally{db.update("ALTER TABLE "+table+" DROP CONSTRAINT s21_fail");}}
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(booleans={false,true})
    void cleanupOnlyRemovesUnboundAppealMaterialsAndSerializesWithSubmission(boolean expired)throws Exception{long id=violation(student,now());String file=file(student,"png");clock.set(base.plusDays(1).atTime(9,0).minusNanos(expired?0:1000));var barrier=new CyclicBarrier(2);var pool=Executors.newFixedThreadPool(2);try{var create=pool.submit(()->{barrier.await();try{appeals.create(student,id,request(List.of(file)));return 200;}catch(Api.Failure e){return e.status;}});var clean=pool.submit(()->{barrier.await();return attachments.cleanupExpired();});int outcome=create.get(20,TimeUnit.SECONDS);clean.get(20,TimeUnit.SECONDS);if(expired)assertTrue(outcome==404||outcome==409);else assertEquals(200,outcome);}finally{pool.shutdownNow();}assertEquals(expired?0:1,db.count("SELECT count(*) FROM appeals"));assertEquals(expired?0:1,db.count("SELECT count(*) FROM evidence_attachments"));}
    @Test void manualViolationSnapshotNeverLeaksReporterReservationComplaintOrPrivateIdentity()throws Exception{long source=reservation(other,seat1);clock.set(base.atTime(10,1));long complaint=Store.id(complaints.create(other,new Requests.Complaint("occupation",source,null,"PRIVATE-S21-REPORTER-COMPLAINT",List.of(),key())),"id");management.accept(admin,complaint,new Requests.ComplaintAccept(1L,key()));long event=Store.id(management.verify(admin,complaint,new Requests.ComplaintVerification(2L,key(),"verified_refusal",now().atZone(BookingPolicy.CAMPUS_ZONE).toOffsetDateTime().toString(),"允许主动公开的核实进度","PRIVATE-S21-FACT",student,true,"PRIVATE-S21-IDENTITY",true,true)),"event_id");var manual=restrictionWorkflow.registerManualViolation(admin,event,new Requests.ManualViolation(key(),"独立面向被登记人的事实说明"));long violation=((Number)((Map<?,?>)manual.get("violation")).get("id")).longValue();var response=appeals.create(student,violation,request(List.of()));String value=json.writeValueAsString(response);assertFalse(value.contains("PRIVATE-S21"));assertFalse(value.contains("complaint_id"));assertFalse(value.contains("source_event_id"));assertFalse(value.contains("identity_basis"));assertNull(((Map<?,?>)((Map<?,?>)response.get("appeal")).get("violation_snapshot")).get("reservation_id"));}
    @Test void adminDetailAloneExposesCurrentManualSourceWhileAllSafeReceiptsAndListsKeepFrozenPrivacy()throws Exception{
        String owner=token("student"),administrator=token("admin"),foreign=token("other");long reservation=reservation(other,seat1);clock.set(base.atTime(10,1));long complaint=Store.id(complaints.create(other,new Requests.Complaint("occupation",reservation,null,"PRIVATE-V83-REPORTER",List.of(),key())),"id");management.accept(admin,complaint,new Requests.ComplaintAccept(1L,key()));long event=Store.id(management.verify(admin,complaint,new Requests.ComplaintVerification(2L,key(),"verified_refusal",now().atZone(BookingPolicy.CAMPUS_ZONE).toOffsetDateTime().toString(),"管理员主动公开的核实进度","PRIVATE-V83-FACTS",student,true,"PRIVATE-V83-IDENTITY",true,true)),"event_id");var registered=restrictionWorkflow.registerManualViolation(admin,event,new Requests.ManualViolation(key(),"独立公开事实说明"));long violation=((Number)((Map<?,?>)registered.get("violation")).get("id")).longValue();var request=request(List.of());var created=http.perform(body(post(createPath(violation)),request,owner)).andExpect(status().isOk()).andExpect(jsonPath("$.data.appeal.management_context").doesNotExist()).andExpect(jsonPath("$.data.appeal.violation_snapshot.reservation_id").isEmpty()).andReturn();long appeal=json.readTree(created.getResponse().getContentAsString()).path("data").path("appeal").path("id").asLong();String originalSnapshot=db.one("SELECT violation_snapshot::text AS snapshot FROM appeals WHERE id=?",appeal).get("snapshot").toString();
        // Explicit test-only changed current status distinguishes live source facts from the immutable submission snapshot.
        db.update("UPDATE violations SET status='revoked' WHERE id=?",violation);
        http.perform(auth(get("/api/admin/appeals/"+appeal),administrator)).andExpect(status().isOk()).andExpect(jsonPath("$.data.management_context.violation.id").value(violation)).andExpect(jsonPath("$.data.management_context.violation.user_id").value(student)).andExpect(jsonPath("$.data.management_context.violation.reservation_id").value(reservation)).andExpect(jsonPath("$.data.management_context.violation.source_event_id").value(event)).andExpect(jsonPath("$.data.management_context.violation.registrant_id").value(admin)).andExpect(jsonPath("$.data.management_context.violation.status").value("revoked")).andExpect(jsonPath("$.data.management_context.violation.occurred_at").value(base+"T10:01+08:00")).andExpect(jsonPath("$.data.management_context.source_complaint_id").value(complaint)).andExpect(jsonPath("$.data.violation_snapshot.status").value("active")).andExpect(jsonPath("$.data.violation_snapshot.reservation_id").isEmpty());
        for(var route:List.of(get("/api/appeals/"+appeal),get("/api/appeals/mine"))){String safe=http.perform(auth(route,owner)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();for(String key:List.of("management_context","source_event_id","source_complaint_id","registrant_id","PRIVATE-V83"))assertFalse(safe.contains(key));}
        http.perform(auth(get("/api/admin/appeals"),administrator)).andExpect(status().isOk()).andExpect(jsonPath("$.data[0].management_context").doesNotExist()).andExpect(jsonPath("$.data[0].violation_snapshot.reservation_id").isEmpty());http.perform(auth(get("/api/admin/appeals/"+appeal),owner)).andExpect(status().isForbidden());http.perform(auth(get("/api/appeals/"+appeal),foreign)).andExpect(status().isForbidden());http.perform(body(post(createPath(violation)),request,owner)).andExpect(status().isOk()).andExpect(jsonPath("$.data.replayed").value(true)).andExpect(jsonPath("$.data.appeal.management_context").doesNotExist()).andExpect(jsonPath("$.data.appeal.violation_snapshot.reservation_id").isEmpty());assertEquals(originalSnapshot,db.one("SELECT violation_snapshot::text AS snapshot FROM appeals WHERE id=?",appeal).get("snapshot"));
    }
    @Test void authOwnerStrictFieldsAndReadOnlyAdminBoundaryAreEnforced()throws Exception{String owner=token("student"),administrator=token("admin"),foreign=token("other");long id=violation(student,now());http.perform(get(eligibilityPath(id))).andExpect(status().isUnauthorized());http.perform(auth(get(eligibilityPath(id)),foreign)).andExpect(status().isForbidden());http.perform(auth(get(eligibilityPath(id)),administrator)).andExpect(status().isForbidden());http.perform(auth(get(eligibilityPath(Long.MAX_VALUE)),owner)).andExpect(status().isNotFound());http.perform(auth(get("/api/admin/appeals"),owner)).andExpect(status().isForbidden());for(String extra:List.of("user_id","notification_id","deadline","status","verification_note")){var body=new LinkedHashMap<String,Object>();body.put("operation_id",key());body.put("description","说明");body.put(extra,"forged");http.perform(body(post(createPath(id)),body,owner)).andExpect(status().isBadRequest());}for(Object ids:List.of(List.of(1),List.of(key(),key(),key(),key()),List.of("invalid"))){http.perform(body(post(createPath(id)),Map.of("operation_id",key(),"description","说明","attachment_ids",ids),owner)).andExpect(status().isBadRequest());}for(String description:List.of(" ","a".repeat(2001))){http.perform(body(post(createPath(id)),new Requests.Appeal(key(),description,List.of()),owner)).andExpect(status().isBadRequest());}long appeal=appealId(appeals.create(student,id,request(List.of())));http.perform(auth(get("/api/appeals/"+appeal),foreign)).andExpect(status().isForbidden());http.perform(auth(get("/api/admin/appeals").param("status",""),administrator)).andExpect(status().isBadRequest());db.update("UPDATE users SET status='disabled' WHERE id=?",staff);assertEquals(403,assertThrows(Api.Failure.class,()->appeals.mine(staff)).status);}
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"png","jpeg"})
    void appealUploadReusesCompleteImageValidationAndRejectsExtraPurposeFields(String format)throws Exception{String owner=token("student");byte[] complete=image(format,12,12),cut=Arrays.copyOf(complete,complete.length-(format.equals("png")?12:2));http.perform(multipart("/api/appeal-attachments").file(new MockMultipartFile("file","cut."+format,"image/"+format,cut)).header("Authorization","Bearer "+owner)).andExpect(status().isBadRequest());http.perform(multipart("/api/appeal-attachments").file(new MockMultipartFile("file","valid."+format,"image/"+format,complete)).param("purpose","complaint").header("Authorization","Bearer "+owner)).andExpect(status().isBadRequest());assertEquals(0,db.count("SELECT count(*) FROM evidence_attachments"));}
